solution:
.avatar {
  display: grid;
  place-items: center;
  width: 64px;
  height: 64px;
  margin: 40px;
  border-radius: 12px;
  background: #3f3f46;
  color: #fafafa;
}

.badge {
  min-width: 22px;
  padding: 2px 6px;
  border-radius: 999px;
  background: #f97316;
  color: #fff;
  font-size: 12px;
  text-align: center;
}

/* ---- Solution ---- */
.avatar {
  position: relative;
}

.badge {
  position: absolute;
  top: 0;
  right: 0;
  transform: translate(50%, -50%);
}
